describe('Duplicate Record Functionality', () => {
  beforeEach(() => {
    cy.visit('/records');
    cy.intercept('GET', '/api/records').as('getRecords');
    cy.intercept('POST', '/api/records/duplicate').as('duplicateRecord');
  });

  it('should successfully duplicate an existing record with one click', () => {
    cy.wait('@getRecords');
    cy.get('[data-testid="record-item-1"]').should('be.visible');
    cy.get('[data-testid="record-title-1"]').should('contain', 'Original Record');

    cy.get('[data-testid="duplicate-button-1"]').click();
    cy.wait('@duplicateRecord');

    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Record duplicated successfully');

    cy.get('[data-testid="record-item-2"]').should('be.visible');
    cy.get('[data-testid="record-title-2"]').should('contain', 'Original Record Copy');
    cy.get('[data-testid="record-id-2"]').should('not.equal', '[data-testid="record-id-1"]');

    cy.get('[data-testid="record-item-2"]').should('have.class', 'duplicated-record');
  });

  it('should handle duplicate request when record does not exist', () => {
    cy.intercept('GET', '/api/records', { statusCode: 404, body: { error: 'Record not found' } }).as('getRecordsNotFound');
    cy.intercept('POST', '/api/records/duplicate', { statusCode: 404, body: { error: 'Record not found' } }).as('duplicateRecordNotFound');

    cy.visit('/records/999');
    cy.get('[data-testid="record-item-999"]').should('not.exist');

    cy.get('[data-testid="duplicate-button-999"]').should('not.exist');

    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Record not found');

    cy.get('[data-testid="duplicate-button-999"]').should('not.exist');
  });
});
